-- Local fixtures only. No remote identity, payment provider or NRHA calls.
begin;
create function pg_temp.test_membership_billing() returns void language plpgsql as $$
declare org uuid:=gen_random_uuid(); directory uuid:=gen_random_uuid(); owner_id uuid:=gen_random_uuid(); rider uuid:=gen_random_uuid(); t uuid:=gen_random_uuid(); taxed uuid:=gen_random_uuid(); legacy public.contact_organization_memberships; m public.contact_organization_memberships; ctx uuid; q jsonb; ch public.billing_charges; f public.billing_folios; cfg jsonb; total_before numeric; result jsonb;
begin
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
 insert into public.organizations(id,name,slug,currency) values(org,'Membership DEMO',org::text,'CAD');
 insert into public.organization_members(organization_id,user_id,role) values(org,'20000000-0000-0000-0000-000000000002','admin');
 insert into public.organization_disciplines(id,organization_id,discipline_id) select directory,org,id from public.disciplines order by id limit 1;
 insert into public.contacts(id,type,first_name,last_name,linked_user_id,created_by_user_id) values(owner_id,'owner','Payer','DEMO','20000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000004'),(rider,'rider','Rider','DEMO',null,'20000000-0000-0000-0000-000000000004');
 insert into public.directory_contacts(organization_discipline_id,contact_id) values(directory,owner_id),(directory,rider);
 insert into public.organization_membership_types(id,organization_id,name,season_year,price,tax_applicable,valid_from,valid_until) values(t,org,'No tax DEMO',extract(year from current_date),75,false,current_date-1,current_date+365),(taxed,org,'Taxed DEMO',extract(year from current_date),100,true,current_date-1,current_date+365);
 insert into public.contact_organization_memberships(organization_id,contact_id,membership_type_id,payer_contact_id,status,sold_by_user_id) values(org,rider,t,rider,'active','20000000-0000-0000-0000-000000000002') returning * into legacy;
 select * into legacy from public.contact_organization_memberships where id=legacy.id;
 assert legacy.invoice_id is not null;
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
 perform public.billing_set_capabilities(org,null,true,true,false);
 ctx:=public.membership_billing_configure(t,'[]');
 assert ctx=public.membership_billing_configure(t,'[]'),'Configuration retry idempotent';
 perform public.membership_billing_configure(taxed,'[{"code":"TPS","name":"TPS","rate":5,"jurisdiction":"CA"},{"code":"TVQ","name":"TVQ","rate":9.975,"jurisdiction":"QC"}]');
 assert not has_table_privilege('authenticated','public.contact_organization_memberships','INSERT');
 assert not has_function_privilege('authenticated','public.membership_billing_charge(uuid,uuid,uuid,uuid,numeric)','EXECUTE');
 q:=public.membership_billing_quote(t);assert (q->>'total')::numeric=75;
 q:=public.membership_billing_quote(taxed);assert (q->>'tax_amount')::numeric=14.98 and (q->>'total')::numeric=114.98;
 perform public.billing_test_error(format('select public.membership_billing_reconcile(%L,80)',legacy.id),'MEMBERSHIP_LEGACY_MANUAL_REVIEW');
 m:=public.membership_billing_reconcile(legacy.id,75,owner_id);
 assert m.billing_charge_id is not null and m.status='draft' and m.activated_at is null;
 assert (select status='void' and total_amount=75 and total_paid=0 from public.invoices where id=legacy.invoice_id),'Legacy original values preserved, invoice voided';
 assert (public.membership_billing_reconcile(legacy.id,75,owner_id)).billing_charge_id=m.billing_charge_id,'No second charge on repeat reconciliation';
 select * into ch from public.billing_charges where id=m.billing_charge_id;
 select * into f from public.billing_folios where id=ch.folio_id;
 assert ch.total=75 and f.version=1;
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000004',true);
 assert public.billing6_owner(f.id),'Purchase appears in the payer account, not an unlinked rider account';
 assert (public.purchase_billed_membership(t,rider,owner_id,75)).id=m.id,'Double click/retry returns same membership';
 perform public.billing_test_error(format('select public.purchase_billed_membership(%L,%L,%L,114.97)',taxed,rider,owner_id),'MEMBERSHIP_QUOTE_CHANGED');
 m:=public.purchase_billed_membership(taxed,rider,owner_id,114.98);
 assert m.status='draft' and m.invoice_id is null;
 assert (select count(*) from public.billing_charges where organization_id=org)=2;
 assert (select count(*) from public.invoices where organization_id=org)=1,'No legacy invoice for new membership';
 select * into ch from public.billing_charges where id=m.billing_charge_id;
 assert ch.total=114.98 and (select count(*) from public.billing_charge_taxes where charge_id=ch.id)=2;
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000005',true);
 perform public.billing_test_error(format('select public.purchase_billed_membership(%L,%L,%L,114.98)',taxed,rider,owner_id),'BILLING_FORBIDDEN');
 perform public.billing_test_error(format('select public.membership_billing_reconcile(%L,75)',legacy.id),'BILLING_FORBIDDEN');
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
 select * into f from public.billing_folios where id=ch.folio_id;
 result:=public.record_billing_payment(gen_random_uuid(),jsonb_build_object('folio_id',f.id,'version',f.version,'amount',50,'method','cash','received_at',clock_timestamp(),'confirmed',true,'allocations',jsonb_build_array(jsonb_build_object('charge_id',ch.id,'amount',50))));
 assert (select status='draft' from public.contact_organization_memberships where id=m.id),'Partial payment does not activate card';
 select * into f from public.billing_folios where id=f.id;
 result:=public.record_billing_payment(gen_random_uuid(),jsonb_build_object('folio_id',ch.folio_id,'version',(select version from public.billing_folios where id=ch.folio_id),'amount',64.98,'method','cash','received_at',clock_timestamp(),'confirmed',true,'allocations',jsonb_build_array(jsonb_build_object('charge_id',ch.id,'amount',64.98))));
 assert (select status='active' and activated_at is not null from public.contact_organization_memberships where id=m.id),'Only full received allocated payment activates card';
end $$;
select pg_temp.test_membership_billing();
rollback;
